from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.support import expected_conditions as EC
from selenium.common.exceptions import TimeoutException
from taf.selenium.gnb.oam.core.common import PagePart


class CustomPagePart(PagePart):
    """
    Basic class, initializes web driver and provides common element operations functions.
    """
    def __init__(self, driver, download_checker=None, screenshot_dir=None):
        super(CustomPagePart, self).__init__(driver)
        self._download_checker = download_checker
        self._screenshot_dir = screenshot_dir

    @property
    def download_checker(self):
        return self._download_checker

    @property
    def driver(self):
        return self._driver

    @property
    def screenshot_dir(self):
        return self._screenshot_dir

    @property
    def download_dir(self):
        return self._download_checker.download_dir if self._download_checker else None

    def clear_text_of_enable_element(self, locator, timeout=60):
        self.wait_for_enable(locator, timeout)
        element = self._driver.find_element(*locator)
        self._clear_text_of_field(element)

    def click_enabled_element_after_visible(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)
        self.click_enabled_element(locator, timeout)

    def wait_until_download_complete(self, start_time, download_timeout=1800):
        return self._download_checker.check(start_time, download_timeout)

    def wait_until_element_is_clickable(self, xpath, timeout=60):
        try:
            self._until(EC.element_to_be_clickable((By.XPATH, xpath)), timeout)
        except TimeoutException:
            msg = 'Element with given xpath: {0} has not been able to click'.format(xpath)
            raise TimeoutException(msg)

    def switch_to_coam_login_tab(self):
        """
        There are three ways to open a new tab or window:
        1. use web driver to execute js script(will open a new window):
            driver.execute_script("window.open('your url','_blank');")
        2. send combination of keys COMMAND + T or CTRL + T to open a new tab on one window(can't work on firefox):
            ActionChains(driver).key_down(Keys.CONTROL).send_keys('t').key_up(Keys.CONTROL).perform()
        3. 1) send combination of keys COMMAND + T or CTRL + T to one element(can't work on firefox)
            driver.find_element_by_tag_name('body').send_keys(Keys.CONTROL + 't')
           2) send key CTRL and click one element to open a new tab:
            ActionChains(self._driver).key_down(Keys.CONTROL).click(element).key_up(Keys.CONTROL).perform()
        """
        link_xpath = "//a[contains(text(), 'Manual')]"
        current_window_handle = self._driver.current_window_handle
        ActionChains(self._driver).key_down(Keys.CONTROL). \
            click(self._driver.find_element_by_xpath(link_xpath)).key_up(Keys.CONTROL).perform()
        self.wait_for_new_window_open([current_window_handle])
        for handle in self._driver.window_handles:
            if handle != current_window_handle:
                self._driver.switch_to_window(handle)
